<?php
declare(strict_types=1);
require_once __DIR__.'/activity_connections.php';
require_once __DIR__.'/activity_privacy.php';
function fitness_stage(int $uid,string $source,array $rows,string $mode='merge'): array {if(!in_array($mode,['merge','replace'],true))throw new FitnessException('Choose merge or replacement for the import.');$stage=['mode'=>$mode,'owner'=>$uid,'source'=>$source,'rows'=>$rows,'revision'=>bin2hex(random_bytes(16)),'expires'=>time()+900];comm_put(fitness_key($uid,'stage'),$stage);return $stage;}
function fitness_confirm_import(int $uid,string $revision): void {comm_lock('fitness.import.'.$uid,static function()use($uid,$revision){$key=fitness_key($uid,'stage');$stage=comm_get($key);if(($stage['owner']??0)!==$uid||($stage['expires']??0)<time()||!hash_equals($stage['revision']??'',$revision))throw new FitnessException('This import preview expired or changed. Choose the file again.');$rows=$stage['rows'];if(($stage['mode']??'replace')==='merge'){$old=comm_get(fitness_key($uid,'data',$stage['source']));if($old&&($old['owner']??0)!==$uid)throw new FitnessException('This import belongs to another Writer.');$merged=[];foreach(array_merge($old['rows']??[],$rows)as$r)$merged[$r['origin'].'|'.$r['id']]=$r;$rows=array_values($merged);if(count($rows)>2000)throw new FitnessException('The merged history exceeds 2,000 activities. Use a reviewed replacement snapshot.');}$data=['owner'=>$uid,'source'=>$stage['source'],'rows'=>$rows,'observed'=>time(),'provenance'=>'Owner-selected file; source not independently verified'];comm_put(fitness_key($uid,'data',$stage['source']),$data);comm_put($key,[]);});}
function fitness_targets_save(int $uid,string $source,array $range,array $input): void {
 $values=fitness_target_input($input);$period=fitness_target_key($range);comm_lock('fitness.targets.'.$uid.'.'.$source,static function()use($uid,$source,$period,$values,$input){$key=fitness_key($uid,'targets',$source);$saved=comm_get($key,['owner'=>$uid,'version'=>0,'periods'=>[]]);if(($saved['owner']??0)!==$uid||(string)($saved['version']??0)!==(string)($input['version']??''))throw new FitnessException('Targets changed in another tab. Reload before saving.');if(!array_filter($values,static fn($v)=>$v!==null))unset($saved['periods'][$period]);else{if(count($saved['periods'])>=1000&&!isset($saved['periods'][$period]))throw new FitnessException('Clear unused period targets before adding another.');$saved['periods'][$period]=$values;}$saved['version']++;comm_put($key,$saved);});
}
function fitness_dispatch(string $path): bool {
 if(!preg_match('~^/write/activity(?:/(template|callback/(?:google_health|strava)))?$~D',$path))return false;
 private_response_headers();header('Referrer-Policy: no-referrer');require_auth();journeys_method(['GET','HEAD','POST']);$uid=(int)current_user()['id'];$owner=(int)(comm_config()['owner']??0);$canConfigure=$owner>0&&$owner===$uid;$error='';$notice='';$report=null;$stage=[];$complete=false;$observed=null;
 if(($_SERVER['REQUEST_METHOD']??'GET')==='HEAD')return true;
 if(str_contains($path,'/callback/')){journeys_method(['GET']);$source=basename($path);try{fitness_complete($source,$uid,$_GET);flash('success','Activity identity returned. Confirm the exact account before reading workouts.');}catch(Throwable $e){flash('error',$e instanceof FitnessException?$e->getMessage():'Activity authorization was not completed. Review the provider setup and start again.');}redirect(url('/write/activity#connections'));}
 if($path==='/write/activity/template'){journeys_method(['GET']);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="activity-import-template.csv"');echo "id,title,type,start_time,end_time,duration_seconds,distance_m,steps,calories_kcal,origin\n";return true;}
 $input=is_post()?$_POST:$_GET;$source=is_string($input['source']??null)?$input['source']:'google_health';$badSource=!isset(fitness_sources()[$source]);if($badSource){$source='google_health';$error='Choose a valid activity source.';}
 try{$range=fitness_range($input);}catch(Throwable){$range=fitness_range([]);$error='Choose valid reporting dates, period and timezone.';}
 if(is_post()){
  verify_csrf();try{
   $action=$_POST['action']??'';if($badSource)throw new FitnessException('Choose a valid activity source.');if($error!==''&&in_array($action,['report','export','save_targets','select_period'],true))throw new FitnessException($error);
   if($action==='configure'){
    if(!$canConfigure)throw new FitnessException('Only the workspace owner can configure provider applications.');fitness_cloud($source);$reserved=$source==='google_health'&&function_exists('publishing_client')?[(string)(publishing_client('google')['client_id']??'')]:[];$application=fitness_client_input($source,$_POST,$reserved);comm_put('activity.client.'.$source,$application);flash('success','Dedicated activity application saved. Existing grants using an older configuration need reconnection.');redirect(url('/write/activity#connections'));
   }
   if($action==='connect'){if(($_POST['consent']??'')!=='1')throw new FitnessException('Review and allow the separate activity read connection.');redirect(fitness_authorize($source,$uid,($_POST['include_private']??'')==='1'));}
   if($action==='confirm'){
    fitness_cloud($source);comm_lock('fitness.'.$uid.'.'.$source,static function()use($uid,$source){$key=fitness_key($uid,'grant',$source);$grant=comm_get($key);if(($grant['owner']??0)!==$uid||($grant['status']??'')!=='pending_confirmation'||!hash_equals($grant['client']??'',fitness_client_fingerprint(fitness_client($source))))throw new FitnessException('This pending activity grant changed. Start again.');if(!hash_equals($grant['identity'],is_string($_POST['identity']??null)?$_POST['identity']:''))throw new FitnessException('Review the exact returned activity identity.');$grant['status']='connected';comm_put($key,$grant);});flash('success','Activity account confirmed. Choose a report period and explicitly read its activities.');redirect(url('/write/activity#connections'));
   }
   if($action==='disconnect'){$remote=fitness_disconnect($uid,$source);flash('success',$remote?'Provider confirmed revocation; local access removed.':'Local access removed. Remote revocation was not confirmed; also remove access in the provider’s app settings.');redirect(url('/write/activity#connections'));}
   if($action==='preview_import'){
    if(($_POST['import_consent']??'')!=='1')throw new FitnessException('Allow this selected activity file to be processed privately.');$upload=$_FILES['activities']??null;if(!is_array($upload)||($upload['error']??1)!==UPLOAD_ERR_OK||!is_string($upload['tmp_name']??null)||!is_uploaded_file($upload['tmp_name'])||filesize($upload['tmp_name'])>2000000)throw new FitnessException('Choose an activity CSV up to 2 MB.');$rows=fitness_csv((string)file_get_contents($upload['tmp_name']),$source);fitness_stage($uid,$source,$rows,is_string($_POST['mode']??null)?$_POST['mode']:'merge');redirect(url('/write/activity?source='.$source.'#import-preview'));
   }
   if($action==='confirm_import'){fitness_confirm_import($uid,fitness_text($_POST['revision']??'',32));flash('success','Reviewed activity import saved privately. Your selected merge or replacement was applied to this source history.');redirect(url('/write/activity?source='.$source.'#reports'));}
   if($action==='cancel_import'){comm_put(fitness_key($uid,'stage'),[]);flash('success','Import preview discarded.');redirect(url('/write/activity'));}
   if($action==='purge'){if(!in_array($source,['health_connect','samsung_health','google_fit'],true))throw new FitnessException('Disconnect the cloud account to remove its access. Cloud activity reports are not stored.');comm_lock('fitness.import.'.$uid,static function()use($uid,$source){comm_put(fitness_key($uid,'data',$source),[]);comm_put(fitness_key($uid,'stage'),[]);});flash('success','This source’s saved activity copy and pending preview were removed.');redirect(url('/write/activity?source='.$source));}
   if($action==='select_period')$notice='Period applied. Set targets now, or read this source when ready.';
   if($action==='save_targets'){fitness_targets_save($uid,$source,$range,$_POST);$notice='Targets saved for this source and calendar period.';}
   elseif(in_array($action,['report','export'],true)){
    if($error!=='')throw new FitnessException($error);
    if($range['start']>time()){$rows=[];$complete=false;$observed=time();}
    elseif(in_array($source,['google_health','strava'],true)){if(!journeys_rate_limit('fitness-read',(string)$uid,8,900))throw new FitnessException('Wait before another cloud activity read.');$snapshot=fitness_read($uid,$source,$range);$complete=$snapshot['complete'];$observed=$snapshot['observed'];$rows=$snapshot['rows'];}
    else{$snapshot=comm_get(fitness_key($uid,'data',$source));if(($snapshot['owner']??0)!==$uid)throw new FitnessException('Import and confirm your own activity file first.');$rows=$snapshot['rows'];$observed=$snapshot['observed'];$complete=($_POST['coverage_complete']??'')==='1';}
    $complete=$complete&&$range['start']<=time();$report=fitness_report($rows,$range,$source);
    if($action==='export'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="private-activities-'.$source.'-'.$range['from'].'.csv"');echo fitness_export($report);return true;}
   }elseif(!in_array($action,['save_targets','select_period'],true))throw new FitnessException('Choose an available activity action.');
  }catch(Throwable $e){$error=$e instanceof FitnessException||$e instanceof FitnessRemoteException?$e->getMessage():'The activity action could not be completed. No provider response or private credential is displayed.';}
 }
 $grants=[];$configured=[];foreach(['google_health','strava']as$p){$g=comm_get(fitness_key($uid,'grant',$p));$grants[$p]=($g['owner']??0)===$uid?array_intersect_key($g,array_flip(['identity','status','scopes','connected_at'])):[];$client=fitness_client($p);$configured[$p]=fitness_configured($client)&&($p!=='google_health'||($client['dedicated_project']??false)===true);if($p==='google_health'&&!$configured[$p]&&$g)$grants[$p]['status']='reconnect';if($g&&isset($g['client'])&&!hash_equals($g['client'],fitness_client_fingerprint($client)))$grants[$p]['status']='reconnect';}
 $stage=comm_get(fitness_key($uid,'stage'));if(($stage['owner']??0)!==$uid||($stage['expires']??0)<time()){$stage=[];comm_put(fitness_key($uid,'stage'),[]);}
 $targets=comm_get(fitness_key($uid,'targets',$source),['owner'=>$uid,'version'=>0,'periods'=>[]]);if(($targets['owner']??0)!==$uid)$targets=['owner'=>$uid,'version'=>0,'periods'=>[]];$targetValues=$range['period']==='custom'?[]:($targets['periods'][fitness_target_key($range)]??[]);$metric=is_string($input['metric']??null)&&isset(fitness_target_fields()[$input['metric']])?$input['metric']:'activities';
 $local=[];foreach(['health_connect','samsung_health','google_fit']as$p){$saved=comm_get(fitness_key($uid,'data',$p));$local[$p]=($saved['owner']??0)===$uid?['count'=>count($saved['rows']??[]),'observed'=>$saved['observed']??null]:null;}
 render_write('activity',compact('source','range','grants','configured','canConfigure','error','notice','report','complete','observed','stage','targets','targetValues','metric','local')+['writeTitle'=>'Activity & fitness']);return true;
}
